def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    prev_bids = []
    strong_prev = 0.0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) > strong_prev:
                    strong_prev = float(bid)

    urgent = hp <= 3 or no_water >= 2
    pressured = hp <= 5 or no_water >= 1

    if not alive:
        if urgent:
            return float(min(budget, 45.0))
        return float(min(budget, 18.0))

    if slots >= 2:
        if urgent:
            target = max(68.0, strong_prev + 2.0)
        elif pressured:
            target = max(52.0, strong_prev * 0.92 + 1.0)
        else:
            if strong_prev >= 78.0:
                target = 34.0
            else:
                target = max(36.0, strong_prev * 0.72)
    else:
        if urgent:
            target = max(88.0, strong_prev + 4.0)
        elif pressured:
            target = max(74.0, strong_prev + 1.5)
        else:
            if strong_prev >= 80.0:
                target = 29.0
            else:
                target = max(41.0, strong_prev * 0.62)

    if budget < target:
        if urgent:
            return float(budget)
        target = max(0.0, budget * 0.82)

    if hp >= 8 and no_water == 0 and strong_prev >= 75.0 and slots == 1:
        target = min(target, 26.0)

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.75

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_hp > 3:
                base_bid = max(base_bid, highest_prev_bid * 1.05)
            else:
                base_bid = max(base_bid, DAILY_SALARY * 0.98)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid * 1.02)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.4)

    final_bid = max(1.0, min(my_budget, base_bid))

    if current_day >= EPISODE_DAYS - 1:
        if my_hp <= 3:
            final_bid = min(my_budget, DAILY_SALARY * 1.05)
        elif my_budget > DAILY_SALARY * 2:
            final_bid = max(final_bid, DAILY_SALARY * 0.9)

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only.
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else 0.0

    # Pressure estimate: if someone previously bid very high, assume they may contest again.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85  # ~119

    # Supply tightness: fewer units means more competition for water.
    # Use thresholds relative to WATER_REQ.
    # Note: indices not used; only numeric comparisons.
    tight = supply < (MIN_SUPPLY + MAX_SUPPLY) / 2.0  # <20
    very_tight = supply <= MIN_SUPPLY  # <=15

    # Base bid targets.
    # Bob's avg ~71.5; aim just above typical contest level.
    target = 0.0

    if my_hp <= 2 or my_no_water_days >= 2:
        # Emergency: bid to secure water.
        if very_tight:
            target = DAILY_SALARY * 0.95
        elif tight:
            target = DAILY_SALARY * 0.75
        else:
            target = DAILY_SALARY * 0.6
    else:
        if high_pressure:
            # If someone already overcommitted, we don't need to match max; we can slightly exceed typical.
            if very_tight:
                target = min(DAILY_SALARY * 0.85, highest_prev_bid * 0.55 + second_prev_bid * 0.25 + 10.0)
            elif tight:
                target = min(DAILY_SALARY * 0.7, max(DAILY_SALARY * 0.55, second_prev_bid + 5.0))
            else:
                target = max(DAILY_SALARY * 0.45, second_prev_bid + 3.0)
        else:
            # Normal: bid around Bob's typical range; adjust for tightness.
            if very_tight:
                target = DAILY_SALARY * 0.65
            elif tight:
                target = DAILY_SALARY * 0.58
            else:
                target = DAILY_SALARY * 0.5

    # Ensure we don't bid more than budget.
    # Also keep some reserve: avoid spending everything unless emergency.
    reserve_frac = 0.15 if (my_hp > 2 and my_no_water_days < 2) else 0.05
    max_affordable = max(0.0, my_budget * (1.0 - reserve_frac))

    bid = float(min(my_budget, max_affordable, target))

    # If target is too low relative to likely contest, bump modestly.
    # Use highest_prev_bid as a cap guide.
    if bid < DAILY_SALARY * 0.45 and tight:
        bid = float(min(my_budget, max_affordable, DAILY_SALARY * 0.55))

    # Avoid zero bids unless budget is tiny.
    if bid <= 0.0:
        bid = float(min(my_budget, DAILY_SALARY * 0.2))

    return float(bid)
